python3 - <<'EOF'
import json,glob,csv
D='/Users/nikolaydidiletsov/Documents/Codex/negotiation-arena-kit/data'
facts=json.load(open(D+'/facts.json'))
print("REL TERMS IN ARENA RESULTS")
for f in sorted(glob.glob('arena_kit/sim_cases/real_runs*/*_P*.json')):
    d=json.load(open(f)); r=d['result']
    if r.get('deal') and d['case'] in ('P01','P02','P03','P10'):
        t=r['terms']; print(f.split('sim_cases/')[1], t['unit_price'], t['payment_days'], t.get('contract_months'), t.get('volume_per_year'), t.get('effective_date'), t.get('index_clause') and t['index_clause']['deadband_pct'], 'rel=',r['cost_breakdown'].get('relationship'))
print("\nSHOULD COST")
for p in ['P01','P02','P03','P10','P05','P04','P07','P08','P11','P18']:
    c=json.load(open(f'arena_kit/sim_cases/real/{p}.json'))
    for part in c['parts']:
        pid=part.split(':')[1]
        for k,v in facts.items():
            if k.startswith('cost:'+pid): print(p, k, v, 'suppliers', c['suppliers'])
print("\nSUPPLIER INTEL / SUPPLIERS")
for sid in ['70110','70510','70530','70410']:
    for k,v in facts.items():
        if sid in k and (k.startswith('sup:') or k.startswith('intel') or 'intel' in k): print(k, json.dumps(v)[:400])
with open(D+'/data/supplier_intel.csv') as fh:
    for row in csv.DictReader(fh):
        if any(s in json.dumps(row) for s in ['70110','70510','70530','70410']): print(row)
with open(D+'/data/suppliers.csv') as fh:
    for row in csv.DictReader(fh):
        if any(s in json.dumps(row) for s in ['70110','70510','70530','70410']): print(row)
EOF

